import { prisma } from '@/lib/prisma';

async function searchProducts(searchTerm: string, minRating: number) {
  return await prisma.product.findMany({
    where: {
      AND: [
        { isArchived: false },
        { rating: { gte: minRating } },
        {
          OR: [
            { title: { contains: searchTerm, mode: 'insensitive' } },
            { description: { contains: searchTerm, mode: 'insensitive' } },
            { tags: { has: searchTerm.toLowerCase() } } // PostgreSQL array check
          ]
        }
      ]
    },
    orderBy: [
      { featured: 'desc' }, // Featured products first
      { rating: 'desc' },   // Then highest rating
      { price: 'asc' }      // Then lowest price
    ],
    take: 20
  });
}
